      const depth = current.depth + 1;
      result.push({ issue, depth });
      queue.push({ id: issue.id, depth });
    }
  }
  return result;
}

async function validateParent(orgId: OrgId, projectId: ProjectId, parentId: IssueId,
  issueId: IssueId, height: number, moving = false): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  requireFound(parent?.projectId === projectId ? parent : null, "Issue", parentId);
  assertNotArchived("Issue", parentId, parent!);
  let current: Issue | null = parent;
  let level = 0;
  const visited = new Set<IssueId>();
  while (current) {
    if ((moving && current.id === issueId) || visited.has(current.id)) {
      throw new IssueHierarchyError(issueId, "cycle");
    }
    visited.add(current.id);
    level++;
    current = current.parentId === null ? null : await issueRepo.findIssueById(orgId, current.parentId);
  }
  if (level + height > MAX_SUB_ISSUE_DEPTH) throw new IssueHierarchyError(issueId, "too_deep");
}

export async function setIssueParent(actor: Actor, input: SetIssueParentInput): Promise<Issue> {
  assertOrgScope(actor, input.orgId);
  const issue = requireFound(await issueRepo.findIssueById(input.orgId, input.issueId), "Issue", input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  const tree = await issueRepo.listHierarchyIssues(input.orgId, issue.projectId);
  const below = descendants(tree, issue.id);
  const height = below.reduce((max, entry) => Math.max(max, entry.depth), 0);
  if (input.parentId !== null) {
    await validateParent(input.orgId, issue.projectId, input.parentId, issue.id, height, true);
  } else if (height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issue.id, "too_deep");
  }
  if (issue.parentId === input.parentId) return issue;
  const after = await issueRepo.setIssueParent(input.orgId, issue.id, input.parentId);
  await emit("issue.updated", { ...actorEnvelope(actor), issueId: after.id, projectId: after.projectId, changedFields: ["parentId"] });
  return after;
}

async function readableTree(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);
  const issue = requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return issueRepo.listHierarchyIssues(orgId, issue.projectId);
}

export async function listSubIssues(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<readonly Issue[]> {
  const tree = await readableTree(actor, orgId, issueId);
  return tree.filter(issue => issue.parentId === issueId && issue.archivedAt === null)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.number - b.number);
}

function rollup(tree: readonly Issue[], issueId: IssueId): IssueRollup {
  const live = descendants(tree, issueId).filter(entry => entry.issue.archivedAt === null);
  const closed = live.filter(entry => CLOSED_ISSUE_STATUSES.includes(entry.issue.status)).length;
  return { total: live.length, open: live.length - closed, closed };
}

export async function getIssueRollup(actor: Actor, orgId: OrgId, issueId: IssueId): Promise<IssueRollup> {
  return rollup(await readableTree(actor, orgId, issueId), issueId);
}

async function notifyCompletedParent(actor: Actor, parentId: IssueId | null): Promise<void> {
  if (parentId === null) return;
  const parent = await issueRepo.findIssueById(actor.orgId, parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) return;
  const tree = await issueRepo.listHierarchyIssues(actor.orgId, parent.projectId);
  if (!tree.some(issue => issue.parentId === parentId)) return;
  if (rollup(tree, parentId).open !== 0) return;
  await notify(actor.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues completed",
    body: `All sub-issues of ${parent.title} are closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
